{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#b59c7c;--muted:#9aa6b2;--glass:rgba(255,255,255,0.03)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#ecf0f3;background:linear-gradient(180deg, #071226 0%, #081222 100%);}
    header{position:sticky;top:0;background:linear-gradient(180deg,rgba(7,10,15,0.6),transparent);backdrop-filter:blur(6px);z-index:40;padding:18px 24px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#7a6a5c);display:flex;align-items:center;justify-content:center;color:#081018;font-weight:700}
    nav a{color:#dbe7ef;text-decoration:none;margin-left:18px;font-size:15px}
    main{padding:42px 24px 120px;max-width:1100px;margin:0 auto}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .hero .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:26px;border-radius:12px;box-shadow:0 6px 30px rgba(2,6,10,0.6)}
    h1{margin:0 0 8px 0;font-size:28px;color:#fff}
    p.lead{margin:0;color:var(--muted);line-height:1.55}
    .values{display:flex;gap:12px;margin-top:18px}
    .pill{padding:8px 12px;background:var(--glass);border-radius:999px;color:var(--muted);font-size:13px}
    section.story{margin-top:22px}
    .two{display:flex;gap:20px;margin-top:18px}
    .card.small{padding:18px}
    footer.cta{position:fixed;right:20px;bottom:20px;background:linear-gradient(135deg,var(--accent),#8f7b65);color:#04101a;padding:14px 18px;border-radius:12px;box-shadow:0 8px 30px rgba(133,107,86,0.18);font-weight:600}
    .meta{font-size:13px;color:var(--muted);margin-top:10px}
    .pattern{position:absolute;inset:0;opacity:0.06;background:url('assets/img/pattern.svg') repeat}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.brand .logo{width:38px;height:38px}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div class="brand">
      <div class="logo">S</div>
      <div>
        <div style="font-weight:700;color:#fff">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Events</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Ways to Pay</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <div class="card">
        <h1>How we make sound that meets you</h1>
        <p class="lead">We shape gatherings so sound acts like a careful passage — not a spectacle. Each offering is assembled from simple materials: tuned bowls, breath, and attentive pacing. Expect warm layers, measured rests, and clear cues so you can arrive without needing to perform.</p>
        <div class="meta">Our facilitators train across somatic, breath, and acoustic practices. We keep groups small and outline clear safety practices before each session.</div>

        <section class="story">
          <h3 style="margin:14px 0 8px 0;color:#fff">A short lineage</h3>
          <p class="lead">This work began as a study in resonance — how tones meet the body and the edge where attention shifts. We borrow from older traditions and keep what works: slow entrance, predictable pacing, and sound choices that invite rather than demand.</p>
        </section>

        <div class="values">
          <div class="pill">Small gatherings</div>
          <div class="pill">Clear guidance</div>
          <div class="pill">Accessible positions</div>
        </div>
      </div>

      <aside class="card small">
        <h4 style="margin:0 0 8px 0;color:#fff">Quick facts</h4>
        <div class="meta">Sessions: 30–90 minutes</div>
        <div class="meta">Group size: 8–18</div>
        <div class="meta">Location: {{CITY}}, {{STATE}}</div>
        <div style="margin-top:12px"><a href="book.html" style="background:#081018;color:var(--accent);padding:10px 12px;border-radius:8px;text-decoration:none;font-weight:700">Reserve a place</a></div>
      </aside>
    </div>

    <section style="margin-top:28px">
      <h3 style="color:#fff;margin:0">Where we differ</h3>
      <div class="two">
        <div class="card small">
          <strong>Practical entry</strong>
          <p class="lead">We outline clear posture options for every body and a step-by-step arrival so the first five minutes aren't mysterious.</p>
        </div>
        <div class="card small">
          <strong>Transparent pricing</strong>
          <p class="lead">Options scale from community tickets to private sessions; add-ons are offered as simple extras, not layered surprises.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px" aria-labelledby="team">
      <h3 id="team" style="color:#fff;margin:0">The people</h3>
      <p class="lead">A small circle of facilitators who share a listening practice. Each session is led by one guide, supported by an assistant when groups grow larger.</p>
    </section>

  </main>

  <a class="cta" href="book.html">Plan a visit</a>

</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#08101a;--card:#07121a;--accent:#c8a87a;--muted:#9fb1bd}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:linear-gradient(180deg,#071021 0%,#08151a 100%);color:#eaf3f7}
    header{padding:14px 20px;display:flex;align-items:center;justify-content:space-between}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    main{max-width:1000px;margin:24px auto;padding:0 20px}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .faq{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .card{background:rgba(255,255,255,0.02);padding:16px;border-radius:10px}
    .q{font-weight:700;color:#fff}
    .a{color:var(--muted);margin-top:6px}
    .notice{background:#2b2f31;color:#fff;padding:12px;border-radius:8px;margin-top:12px}
    .selector{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}
    select,button{padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:inherit}
    .seats{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
    .seat{width:48px;height:36px;border-radius:8px;background:rgba(255,255,255,0.02);display:flex;align-items:center;justify-content:center;cursor:pointer}
    .seat.selected{background:linear-gradient(180deg,var(--accent),#92735a);color:#081018}
    .pack{margin-top:12px;color:var(--muted)}
    .disclaimer{font-size:13px;color:#f6d7c4;background:rgba(196,134,111,0.06);padding:12px;border-radius:8px;margin-top:12px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,#c8a87a,#7b6350);display:flex;align-items:center;justify-content:center;font-weight:700;color:#081018">S</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Events</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <h1>Questions people bring</h1>
      <p style="color:var(--muted);margin-top:6px">Practical answers so you can arrive with less guesswork. If you still need help, reach out at {{EMAIL}}.</p>
    </div>

    <div class="faq">
      <div>
        <div class="card">
          <div class="q">What should I wear?</div>
          <div class="a">Comfortable layers that let you relax. Bare feet or socks are fine. You will usually lie or sit on floor props; bring clothing that stays warm when still.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <div class="q">How loud is it?</div>
          <div class="a">Sound is mixed for warmth, not startling peaks. We avoid abrupt high-volume strikes. If you’re sensitive to sound, let us know and we will place you where it’s gentlest.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <div class="q">Can I fall asleep?</div>
          <div class="a">Yes. Falling asleep is a normal response and welcomed. We include clear cues at the end to help reorient.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <div class="q">Contraindications</div>
          <div class="a">If you have recent head injury, epilepsy, uncontrolled mental health conditions, or are pregnant without medical clearance, please consult your provider before attending. Inform us of implants or devices sensitive to vibration. This information is not a replacement for medical advice.</div>
          <div class="disclaimer">If in doubt, contact your clinician. For urgent medical concerns do not attend.</div>
        </div>

      </div>

      <aside>
        <div class="card">
          <strong>Try this: pick a spot</strong>
          <p style="color:var(--muted);margin-top:8px">Choose a date and seat type to generate a short packing list for your visit.</p>

          <div class="selector">
            <select id="dateSelect">
              <option value="2026-02-28">Sat, Feb 28 — Evening</option>
              <option value="2026-03-06">Fri, Mar 6 — Night</option>
              <option value="2026-03-14">Sun, Mar 14 — Afternoon</option>
            </select>
            <select id="typeSelect">
              <option value="mat">Floor mat + blanket</option>
              <option value="chair">Folding chair</option>
              <option value="bolster">Bolster + pillow</option>
            </select>
            <button id="genPack">Make list</button>
          </div>

          <div class="seats" id="seats"></div>
          <div class="pack" id="packing"></div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong>Need private support?</strong>
          <p style="color:var(--muted);margin-top:8px">We offer adapted individual sessions for people wanting a tailored pace. See "Private" on the nav or <a href="private-sessions.html">learn more</a>.</p>
        </div>
      </aside>
    </div>

  </main>

  <script>
    // Seat selector and packing list generator (local-only)
    const seatsEl = document.getElementById('seats');
    const packingEl = document.getElementById('packing');
    const genBtn = document.getElementById('genPack');

    const createSeats = ()=>{
      seatsEl.innerHTML = '';
      for(let i=1;i<=12;i++){
        const b = document.createElement('button');
        b.className='seat';
        b.textContent = i;
        b.dataset.num = i;
        b.addEventListener('click',()=>{
          b.classList.toggle('selected');
          updatePacking();
        });
        seatsEl.appendChild(b);
      }
    };

    const updatePacking = ()=>{
      const selected = Array.from(document.querySelectorAll('.seat.selected')).map(s=>s.dataset.num);
      const type = document.getElementById('typeSelect').value;
      if(selected.length===0){
        packingEl.textContent = 'No seats selected yet.';
        return;
      }
      const items = ['Water bottle','Soft cushion/blanket','Socks','Mask (if you prefer)'];
      if(type==='mat') items.unshift('Yoga mat');
      if(type==='bolster') items.unshift('Supportive bolster');
      if(type==='chair') items.unshift('Compact cushion');
      packingEl.innerHTML = '<strong>Selected seats:</strong> '+selected.join(', ')+'\n\n<strong>Suggested items:</strong> '+items.join(', ');
    };

    genBtn.addEventListener('click',()=>{
      const date = document.getElementById('dateSelect').value;
      const type = document.getElementById('typeSelect').value;
      alert('Generated packing list for '+date+' ('+type+'). See the right column for details.');
      updatePacking();
    });

    createSeats();
    updatePacking();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#081018;--card:#0b1520;--accent:#b78f66;--muted:#9bb0bc}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:linear-gradient(180deg,#061018 0%,#08121a 100%);color:#eaf3f7}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    main{max-width:1100px;margin:18px auto;padding:0 20px}
    .split{display:grid;grid-template-columns:1fr 420px;gap:20px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    h1{margin:0 0 8px 0}
    label{display:block;margin-top:12px;font-size:14px}
    select,input[type="text"],textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .planner{margin-top:12px}
    .options{display:flex;gap:8px;margin-top:8px}
    .opt{padding:8px 10px;border-radius:8px;background:rgba(255,255,255,0.02);cursor:pointer}
    .opt.active{background:linear-gradient(180deg,var(--accent),#8f7358);color:#081018}
    .summary{white-space:pre-wrap;background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;margin-top:12px}
    .copy{margin-top:8px;padding:10px 12px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#8f7358);color:#081018;border:none;cursor:pointer}
    .seats{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
    .seat{width:44px;height:36px;border-radius:8px;background:rgba(255,255,255,0.02);display:flex;align-items:center;justify-content:center;cursor:pointer}
    .seat.taken{background:#2c2f33;color:#777}
    .seat.selected{background:linear-gradient(180deg,#ffd9b6,#c9a07a);color:#081018}
    .booking-actions{display:flex;gap:8px;margin-top:12px}
    .btn-primary{background:linear-gradient(135deg,var(--accent),#886b4f);padding:10px 12px;border-radius:8px;border:none;color:#081018;font-weight:700;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}
    @media(max-width:960px){.split{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,#b78f66,#7b5f48);display:flex;align-items:center;justify-content:center;font-weight:700;color:#081018">S</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Events</a>
      <a href="pricing.html">Pricing</a>
      <a href="faq.html">FAQ</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <h1>Plan a session</h1>
    <p class="muted">Use the planner to craft a short program and lock a seat. The summary can be copied and saved for your records.</p>

    <div class="split" role="region">
      <div>
        <div class="card">
          <label for="sessionName">Your name</label>
          <input id="sessionName" type="text" placeholder="First & last">

          <label style="margin-top:12px">Session length</label>
          <div class="options planner" id="lengthOpts">
            <div class="opt" data-val="30">30 min</div>
            <div class="opt active" data-val="60">60 min</div>
            <div class="opt" data-val="90">90 min</div>
          </div>

          <label>Focus (choose up to 2)</label>
          <div class="options" id="focusOpts">
            <div class="opt" data-val="rest">Deep rest</div>
            <div class="opt" data-val="sleep">Sleep prep</div>
            <div class="opt" data-val="reset">Stress release</div>
            <div class="opt" data-val="clarity">Mental clarity</div>
          </div>

          <label>Accessibility notes</label>
          <textarea id="notes" rows="3" placeholder="Tell us about mobility, noise sensitivity, etc."></textarea>

          <div class="booking-actions">
            <button id="build" class="btn-primary">Build plan</button>
            <button id="clear" style="padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:var(--muted)">Reset</button>
          </div>

          <div class="summary" id="planSummary" aria-live="polite">Your personalized plan will appear here.</div>
          <button class="copy" id="copyPlan">Copy summary</button>
        </div>

        <div class="card" style="margin-top:12px">
          <h3 style="margin:0">Seat selection</h3>
          <p class="muted">Choose a date then pick a seat. This is a local demo — no real reservation is made.</p>

          <label style="margin-top:8px">Date</label>
          <select id="eventDate">
            <option value="2026-02-28">Sat, Feb 28 — 7:00pm</option>
            <option value="2026-03-06">Fri, Mar 6 — 7:30pm</option>
            <option value="2026-03-14">Sun, Mar 14 — 4:00pm</option>
          </select>

          <div class="seats" id="bookSeats" aria-hidden="false" style="margin-top:12px"></div>

          <div style="margin-top:12px" class="muted">Selected: <span id="seatChosen">none</span></div>
          <div style="margin-top:12px"><button id="confirm" class="btn-primary">Confirm (demo)</button></div>

          <div class="muted" style="margin-top:12px">If you need help by phone: {{PHONE}}</div>
        </div>

      </div>

      <aside>
        <div class="card">
          <h3 style="margin:0">What to bring</h3>
          <p class="muted">We offer a quick generator: choose your seat type to get a compact packing list.</p>

          <label style="margin-top:8px">Seat type</label>
          <select id="seatType">
            <option value="mat">Floor mat</option>
            <option value="chair">Chair</option>
            <option value="bolster">Bolster</option>
          </select>

          <div style="margin-top:8px"><button id="genBring" class="btn-primary">Generate list</button></div>
          <div class="summary" id="bringList">Nothing yet — generate a list.</div>

          <div style="margin-top:12px;color:var(--muted)"><strong>Access needs?</strong> Add notes in the planner above or email {{EMAIL}}.</div>

        </div>

        <div class="card" style="margin-top:12px">
          <strong>Contraindications & safety</strong>
          <p class="muted" style="margin-top:8px">Please consult your medical provider if you have recent head injury, seizure disorder, or other conditions sensitive to vibration or sound. If pregnant, seek clearance. Notify our team of implants or medical devices.</p>
        </div>
      </aside>
    </div>

  </main>

  <script>
    // Session planner logic
    const lengthOpts = document.getElementById('lengthOpts');
    const focusOpts = document.getElementById('focusOpts');
    const buildBtn = document.getElementById('build');
    const clearBtn = document.getElementById('clear');
    const planDiv = document.getElementById('planSummary');
    const copyBtn = document.getElementById('copyPlan');

    lengthOpts.addEventListener('click', (e)=>{
      if(!e.target.classList.contains('opt')) return;
      Array.from(lengthOpts.children).forEach(n=>n.classList.remove('active'));
      e.target.classList.add('active');
    });

    focusOpts.addEventListener('click',(e)=>{
      if(!e.target.classList.contains('opt')) return;
      // toggle but limit to 2
      const active = Array.from(focusOpts.querySelectorAll('.opt.active'));
      if(e.target.classList.contains('active')){ e.target.classList.remove('active'); return; }
      if(active.length>=2){
        active[0].classList.remove('active');
      }
      e.target.classList.add('active');
    });

    buildBtn.addEventListener('click',()=>{
      const name = document.getElementById('sessionName').value || 'Guest';
      const length = lengthOpts.querySelector('.opt.active').dataset.val;
      const foci = Array.from(focusOpts.querySelectorAll('.opt.active')).map(n=>n.dataset.val);
      const notes = document.getElementById('notes').value || 'None';
      const summary = [
        'Session Plan for: '+name,
        'Length: '+length+' min',
        'Focus: '+(foci.length?foci.join(', '):'General'),
        '',
        'Accessibility notes:',
        notes,
        '',
        'Arrival: arrive 10–15 minutes early; bring what you need to be still and warm.'
      ].join('\n');
      planDiv.textContent = summary;
    });

    clearBtn.addEventListener('click',()=>{
      document.getElementById('sessionName').value='';
      document.getElementById('notes').value='';
      Array.from(lengthOpts.children).forEach((n,i)=>{n.classList.toggle('active', i===1)});
      Array.from(focusOpts.children).forEach(n=>n.classList.remove('active'));
      planDiv.textContent='Your personalized plan will appear here.';
    });

    copyBtn.addEventListener('click',async ()=>{
      const text = planDiv.textContent;
      try{ await navigator.clipboard.writeText(text); copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy summary',1200);}catch(e){alert('Copy not supported');}
    });

    // Seat map (fake)
    const seatContainer = document.getElementById('bookSeats');
    const seatChosen = document.getElementById('seatChosen');
    const confirmBtn = document.getElementById('confirm');
    let seatsState = []; // 0 free, 1 taken, 2 selected

    const renderSeats = ()=>{
      seatContainer.innerHTML='';
      seatsState.forEach((s,i)=>{
        const b = document.createElement('button');
        b.className='seat'+(s===1?' taken':'')+(s===2?' selected':'');
        b.textContent=i+1;
        b.addEventListener('click',()=>{
          if(s===1) return; // taken
          // clear previous selection
          seatsState = seatsState.map(x=>x===2?0:x);
          seatsState[i] = 2;
          updateDisplay();
          renderSeats();
        });
        seatContainer.appendChild(b);
      });
    };

    const updateDisplay = ()=>{
      const sel = seatsState.findIndex(s=>s===2);
      seatChosen.textContent = sel===-1? 'none': String(sel+1);
    };

    const randomizeTaken = ()=>{
      seatsState = Array.from({length:12}, ()=> Math.random()>0.8?1:0);
      renderSeats(); updateDisplay();
    };

    document.getElementById('eventDate').addEventListener('change',()=>{
      randomizeTaken();
    });

    confirmBtn.addEventListener('click',()=>{
      const sel = seatsState.findIndex(s=>s===2);
      if(sel===-1){ alert('Please pick a seat first.'); return; }
      alert('Demo reservation confirmed for seat '+(sel+1)+'. This is a local demo only.');
    });

    // Packing list generator
    const genBring = document.getElementById('genBring');
    const bringList = document.getElementById('bringList');
    genBring.addEventListener('click',()=>{
      const type = document.getElementById('seatType').value;
